import 'dart:io';
import 'package:dio/io.dart';

Future<Dio> createPinnedDio() async {
  final pem = await rootBundle.load('assets/certs/api_example_com.pem');
  final ctx = SecurityContext(withTrustedRoots: false)
    ..setTrustedCertificatesBytes(pem.buffer.asUint8List());

  final dio = Dio(BaseOptions(baseUrl: 'https://api.example.com'));
  (dio.httpClientAdapter as IOHttpClientAdapter).createHttpClient =
      () => HttpClient(context: ctx);   // every other chain fails the handshake
  return dio;
}

// ── Approach 2: hash comparison, as a second line of defence ──
// Compute the SPKI pin:
//   openssl s_client -connect api.example.com:443 | openssl x509 -pubkey -noout |\
//   openssl pkey -pubin -outform der | openssl dgst -sha256 -binary | base64
const _pins = {
  'primary-pin-base64=',   // current key
  'backup-pin-base64=',    // next key — rotate before the primary expires
};

bool verifyPin(X509Certificate cert) =>
    _pins.contains(base64Encode(sha256.convert(cert.der).bytes));
// NOTE: cert.der is the whole certificate, not the SPKI. Pulling the public key
// out needs an ASN.1 parser (package:asn1lib) or a native pinning library.

