// go_router: one guarded entry point for every incoming link
final router = GoRouter(
  redirect: (context, state) {
    final loggedIn = ref.read(authProvider).valueOrNull != null;
    // ✅ session is re-checked on arrival, whatever the link claimed
    if (!loggedIn && _protected.hasMatch(state.matchedLocation)) {
      return '/login?next=${Uri.encodeComponent(state.matchedLocation)}';
    }
    return null;
  },
  errorBuilder: (_, __) => const NotFoundPage(),   // ✅ unknown path, not a guess
  routes: [
    GoRoute(
      path: '/order/:id',
      builder: (_, s) {
        final id = int.tryParse(s.pathParameters['id'] ?? '');
        // ✅ validate shape, then let the server authorize the fetch
        if (id == null) return const NotFoundPage();
        return OrderPage(orderId: id);
      },
    ),
    GoRoute(
      path: '/open',
      builder: (_, s) {
        final raw = s.uri.queryParameters['url'] ?? '';
        final host = Uri.tryParse(raw)?.host;
        // ❌ WebViewPage(url: raw) would be an open redirect
        return _allowedHosts.contains(host)
            ? WebViewPage(url: raw)
            : const NotFoundPage();
      },
    ),
  ],
);

