import 'package:local_auth/local_auth.dart';
import 'package:flutter_secure_storage/flutter_secure_storage.dart';

final _auth = LocalAuthentication();
const _storage = FlutterSecureStorage(
  iOptions: IOSOptions(
    accessibility: KeychainAccessibility.first_unlock_this_device,
    accessControlFlags: [AccessControlFlag.biometryCurrentSet], // ✅ dies on new enrollment
  ),
  aOptions: AndroidOptions(encryptedSharedPreferences: true),
);

Future<String?> unlockRefreshToken() async {
  if (!await _auth.isDeviceSupported()) return null;          // no hardware / no passcode
  final available = await _auth.getAvailableBiometrics();
  if (available.isEmpty) return null;                          // nothing enrolled

  try {
    final ok = await _auth.authenticate(
      localizedReason: 'Unlock your account',
      options: const AuthenticationOptions(
        biometricOnly: false,   // passcode fallback is a real credential
        stickyAuth: true,       // survive an interruption, do not silently fail
      ),
    );
    if (!ok) return null;
  } on PlatformException catch (e) {
    if (e.code == 'LockedOut' || e.code == 'PermanentlyLockedOut') {
      return null;             // ✅ force password sign-in, do not retry silently
    }
    rethrow;
  }

  // The read itself is what the biometric protects — the boolean above is only UX
  return _storage.read(key: 'refresh_token');
}

