// ✅ Real secret — the client never sees it; your backend holds it
class PaymentsRepository {
  PaymentsRepository(this._dio);
  final Dio _dio;

  Future<Receipt> charge(Cart cart) async {
    // Session cookie / bearer token identifies the user;
    // the server talks to Stripe with the secret key it alone holds.
    final res = await _dio.post('/v1/checkout', data: cart.toJson());
    return Receipt.fromJson(res.data as Map<String, dynamic>);
  }
}

